		if ctx.App.Suggest {
			if suggestion := SuggestCommand(ctx.App.Commands, command); suggestion != "" {
				errMsg += ". " + suggestion
			}
		}
		return Exit(errMsg, 3)
	}

	ctx.App.CommandNotFound(ctx, command)
	return nil
}
